window.docContents[12].resolve({"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Exemplos-Resolvidos/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Exemplos-Resolvidos--A-Disjun______o-Comuta":{"contents":"A análise de casos sobre a disjunção a remonta com os disjuntos trocados.\n\n               [P]           [Q]\n   [P ∨ Q]    ─────── ∨I₂   ─────── ∨I₁\n              Q ∨ P         Q ∨ P\n  ───────────────────────────────────── ∨E\n             Q ∨ P\n  ──────────────────────  →I\n   P ∨ Q → Q ∨ P\n\n\nexample (P Q : Prop) : P ∨ Q → Q ∨ P :=\n  fun h => h.elim\n    (fun hP => Or.inr hP)\n    (fun hQ => Or.inl hQ)\n\n\nexample (P Q : Prop) : P ∨ Q → Q ∨ P := by\n  intro h\n  cases h with\n  | inl hP => exact Or.inr hP\n  | inr hQ => exact Or.inl hQ\n\n\n","context":"Verificação Formal de Software\u0009Aula 1: Motivação e Lógica Proposicional\u0009Exemplos Resolvidos","header":"1.8.4. A Disjunção Comuta","id":"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Exemplos-Resolvidos/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Exemplos-Resolvidos--A-Disjun______o-Comuta"}});